CREATE OR REPLACE FUNCTION public.rsc_condition_decision_seal_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior jsonb; next_row jsonb;
BEGIN
    IF TG_OP<>'INSERT' THEN prior:=to_jsonb(OLD); END IF;
    IF TG_OP<>'DELETE' THEN next_row:=to_jsonb(NEW); END IF;
    IF NOT public.rsc_condition_decision_seal_relevant(TG_TABLE_NAME,prior)
       AND NOT public.rsc_condition_decision_seal_relevant(TG_TABLE_NAME,next_row) THEN
        IF TG_OP='DELETE' THEN RETURN OLD; END IF;
        RETURN NEW;
    END IF;
    IF current_setting('transaction_isolation')<>'read committed' THEN
        RAISE EXCEPTION 'condition decision seal fence requires read committed' USING ERRCODE='23514'; END IF;
    PERFORM 1 FROM public.inventory_ledger_heads WHERE stream_key='inventory' FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'condition decision seal fence ledger head required' USING ERRCODE='23514'; END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $function$

